import { afterEach, describe, expect, it, vi } from "vitest";
import { collectSessionStartMessages, runSessionStart } from "./sessionStart.js";
vi.mock("../buildInfo.js", () => ({
    isDevBuildActive: () => false,
    getDevBuildSummary: () => null,
    formatDevBuildBannerLines: () => [],
}));
vi.mock("../config.js", () => ({
    hasCredentials: vi.fn(() => false),
}));
vi.mock("../updates.js", () => ({
    checkForUpdate: vi.fn(),
    detectLegacyInstall: () => false,
    legacyMigrationMessage: () => "",
}));
vi.mock("../sdkUpdates.js", () => ({
    checkForSdkUpdatesOffline: () => [],
    formatSdkUpdateLine: () => "",
}));
import { hasCredentials } from "../config.js";
import { checkForUpdate } from "../updates.js";
const testPlatform = {
    authPath: "test",
    loginHint: "/test:login",
    setupHint: "/test:setup",
    updateHint: "/test:update",
    repo: "Test/test-plugin",
    remotePackageJsonPath: "package.json",
    cliBinary: "test",
    displayName: "Test",
    supportsAutoUpdate: false,
    marketplaceName: "test",
    pluginName: "test",
    marketplacePreRegistered: false,
    pluginUpdateCommands: [],
};
async function captureOutput() {
    let output = "";
    const spy = vi
        .spyOn(process.stdout, "write")
        .mockImplementation((chunk) => {
        output += chunk.toString();
        return true;
    });
    try {
        await runSessionStart("0.0.1", testPlatform);
    }
    finally {
        spy.mockRestore();
    }
    return output;
}
describe("runSessionStart", () => {
    afterEach(() => {
        vi.mocked(hasCredentials).mockReturnValue(false);
    });
    it("tells the user to log in (not run setup) when unauthenticated", async () => {
        const output = await captureOutput();
        const parsed = JSON.parse(output);
        expect(parsed.systemMessage).toContain("[Bitfab] Not authenticated. Run /test:login to log in.");
        expect(parsed.systemMessage).not.toContain("/test:setup");
    });
    it("emits no auth message when authenticated", async () => {
        vi.mocked(hasCredentials).mockReturnValue(true);
        const output = await captureOutput();
        const parsed = output ? JSON.parse(output) : {};
        expect(parsed.systemMessage ?? "").not.toContain("Not authenticated");
    });
    it("does not inject retired browser lifecycle instructions", async () => {
        vi.mocked(hasCredentials).mockReturnValue(true);
        const output = await captureOutput();
        expect(output).not.toContain("Studio");
        expect(output).not.toContain("BLOCKS");
    });
});
describe("update notice", () => {
    const updatablePlatform = {
        ...testPlatform,
        supportsAutoUpdate: true,
    };
    afterEach(() => {
        vi.mocked(hasCredentials).mockReturnValue(true);
    });
    function updateAvailable() {
        vi.mocked(checkForUpdate).mockResolvedValue({
            current: "0.0.1",
            latest: "0.0.2",
            updateAvailable: true,
            autoUpdateEnabled: false,
            staleSameVersion: false,
        });
    }
    it("offers only the update command on a host with no auto-update setting", async () => {
        updateAvailable();
        const messages = await collectSessionStartMessages("0.0.1", updatablePlatform);
        expect(messages.join("\n")).toContain("Run /test:update to update.");
        expect(messages.join("\n")).not.toContain("Marketplaces");
    });
    it("points at the host's own auto-update setting when it has one", async () => {
        updateAvailable();
        const messages = await collectSessionStartMessages("0.0.1", {
            ...updatablePlatform,
            enableAutoUpdateHint: "/plugin → Marketplaces → test → Enable auto-update",
        });
        expect(messages.join("\n")).toContain("or enable auto-update: /plugin → Marketplaces → test → Enable auto-update");
    });
});
